/// <summary>
///    AVA <c>initCustomerFromBusinessRelation</c> method.
/// </summary>
/// <param name="_smmBusRelTable">
///    <c>smmBusRelTable</c> as type
/// </param>
/// <param name="_custAccount">
///    <c>CustAccount</c> as type
/// </param>
/// <returns>
///    <c>CustTable</c> as return value
/// </returns>
protected CustTable initCustomerFromBusinessRelation(smmBusRelTable _smmBusRelTable, CustAccount _custAccount)
{
    CustTable   custTable;

    custTable                       =  next initCustomerFromBusinessRelation(_smmBusRelTable,_custAccount);

    custTable.KCS_LimitGroupName    = _smmBusRelTable.KCS_LimitGroupName;
    custTable.KCS_MaxBonusAmount    = _smmBusRelTable.KCS_MaxBonusAmount;
    custTable.AVASendExcel          = _smmBusRelTable.AVASendExcel;
    custTable.PaymTermId            = _smmBusRelTable.KCS_CRMPaymTermId;
    custTable.PaymMode              = _smmBusRelTable.KCS_CRMPaymMode;
    custTable.CashDisc              = _smmBusRelTable.KCS_CRMCashDisc;
    custTable.SalesGroup            = _smmBusRelTable.KCS_SalesGroup;

    return custTable;
}

/// <summary>
///    AVA <c>initCustTable</c> method.
/// </summary>
/// <returns>
///    <c>CustTable</c> as return value
/// </returns>
protected CustTable initCustTable()
{
    CustTable custTable;
    MandatoryCreditLimit        mandatoryCreditLimit;
    smmCreditMaxMST             creditMax;
    smmCreditRating             creditRating;

    //die drei Felder nicht vom Interessent übernehmen
    custTable = CustTable::findByPartyRecId(this.Party, false);
    if (custTable)
    {
        mandatoryCreditLimit    = custTable.MandatoryCreditLimit;
        creditMax               = custTable.CreditMax;
        creditRating            = custTable.CreditRating;
    }

    custTable                       = next initCustTable();

    custTable.KCS_LimitGroupName    = this.KCS_LimitGroupName;
    custTable.KCS_MaxBonusAmount    = this.KCS_MaxBonusAmount;
    custTable.AVASendExcel          = this.AVASendExcel;
    custTable.PaymTermId            = this.KCS_CRMPaymTermId;
    custTable.PaymMode              = this.KCS_CRMPaymMode;
    custTable.CashDisc              = this.KCS_CRMCashDisc;
    custTable.SalesGroup            = this.KCS_SalesGroup;

    //die drei Felder nicht vom Interessent übernehmen
    if (custTable)
    {
        custTable.MandatoryCreditLimit  = mandatoryCreditLimit;
        custTable.CreditMax             = creditMax;
        custTable.CreditRating          = creditRating;
    }

    return custTable;
}

/// <summary>
///    AVA <c>NDX_initSalesGroupAndDistrictFromAddr</c> method.
/// </summary>
/// <param name="_zipCode">
///    <c>AddressZipCodeId</c> as type
/// </param>
/// <param name="_country">
///    <c>AddressCountryRegionId</c> as type
/// </param>
/// <param name="_dataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
public void NDX_initSalesGroupAndDistrictFromAddr(  AddressZipCodeId        _zipCode,
                                                    AddressCountryRegionId  _country,
                                                    DataAreaId              _dataAreaId)
{
    SmmBusRelSalesDistrictGroup     smmBusRelSalesDistrictGroup;

    smmBusRelSalesDistrictGroup     = AVAKBVHelperClass::ZipCode2SalesDistrict(_zipCode, _country, _dataAreaId);

    if(!this.KCS_SalesGroup)
    {
        this.KCS_SalesGroup = smmBusRelSalesDistrictGroup.KCS_KBVCommissSalesGroup;
    }
    if(!this.SalesDistrict)
    {
        this.SalesDistrict = smmBusRelSalesDistrictGroup.SalesDistrictId;
    }
    if(!this.MainContactWorker)
    {
        this.MainContactWorker = SmmSalesUnit::AVAgetSalesUnitManager(smmBusRelSalesDistrictGroup.KCS_KBVsmmSalesUnitId, false);
    }
}

