/// <summary>
/// Retrieves the primary postal address for the contact of the party at the specified date.
/// </summary>
/// <param name="_transDateTime">
/// The primary postal address date.
/// </param>
/// <param name="_forUpdate">
/// A Boolean value that specifies whether to update the address.
/// </param>
/// <returns>
/// The primary postal address.
/// </returns>
public LogisticsPostalAddress findPrimaryAddress(   TransDateTime   _transDateTime  = DateTimeUtil::getSystemDateTime(), 
                                                    boolean         _forUpdate      = false)
{
    LogisticsPostalAddress address = DirParty::primaryPostalAddress(this.Party, _transDateTime);
    if (_forUpdate)
    {
        address.selectForUpdate(_forUpdate);
    }

    return address;
}

