/// <summary>
/// AVA <c>AVAafterInsert</c> method.
/// </summary>
/// <param name="_logisticsPostalAddress">
///    <c>LogisticsPostalAddress</c> as type
/// </param>
public void AVAafterInsert(LogisticsPostalAddress _logisticsPostalAddress = this.findPrimaryAddress())
{
    smmBusRelTable          locsmmBusRelTable;
    LogisticsPostalAddress  locLogisticsPostalAddress;

    locLogisticsPostalAddress = _logisticsPostalAddress;
    if(!locLogisticsPostalAddress.RecId)
    {
        locLogisticsPostalAddress = this.findPrimaryAddress();
    }

    ttsBegin;
    locsmmBusRelTable = smmBusRelTable::findRec(this.RecId, true);
    locsmmBusRelTable.AVAinitSalesGroupAndDistrictFromAddr(locLogisticsPostalAddress);
    locsmmBusRelTable.MainContactWorker = SmmSalesUnit::AVAgetSalesUnitManager(smmBusRelSalesDistrictGroup::avaFind(locsmmBusRelTable.SalesDistrict).KCS_KBVsmmSalesUnitId, false);
    locsmmBusRelTable.update();
    ttscommit;

    this.AVAcreateContactPersonFromGlobal(true);
}

/// <summary>
///    AVA <c>AVAinitSalesGroupAndDistrictFromAddr</c> method.
/// </summary>
/// <param name="_logisticsPostalAddress">
///    <c>LogisticsPostalAddress</c> as type
/// </param>
public void AVAinitSalesGroupAndDistrictFromAddr(LogisticsPostalAddress _logisticsPostalAddress = null)
{
    LogisticsPostalAddress  locLogisticsPostalAddress;

    locLogisticsPostalAddress = _logisticsPostalAddress;

    if(!locLogisticsPostalAddress.RecId)
    {
        locLogisticsPostalAddress = this.findPrimaryAddress();
    }
    if(locLogisticsPostalAddress.RecId)
    {
        this.NDX_initSalesGroupAndDistrictFromAddr( locLogisticsPostalAddress.ZIPCode,
                                                    locLogisticsPostalAddress.CountryRegionId,
                                                    this.dataAreaId);
    }
}

/// <summary>
///    AVA <c>AVAcreateContactPersonFromGlobal</c> method.
/// </summary>
/// <param name="_checkIfContactPersonExist">
///    <c>boolean</c> as type
/// </param>
public void AVAcreateContactPersonFromGlobal(boolean _checkIfContactPersonExist = false)
{
    ContactPerson   contactPerson;
    ContactPerson   newContactPerson;

    if (this.Party == 0)
    {
        return;
    }

    while select crosscompany * 
    from    contactPerson
    where   contactPerson.ContactForParty == this.Party
    {
        changeCompany(this.company())
        {
            if (_checkIfContactPersonExist == true)
            {
                if (ContactPerson::findNameParty(contactPerson.ContactForParty, contactPerson.PersonName()).RecId != 0)
                {
                    continue;
                }
            }
            /*  2009
            // Kontakt nur anlegen, wenn die Beziehung aktiv ist
            if (DirPartyRelationship::find(DirRelationshipTypeTable::findBySystemType(DirSystemRelationshipType::ContactPerson).RelationshipTypeId, this.PartyId, contactPerson.PartyId).Status == DirRelationshipStatus::Inactive)
            {
                continue;
            }
            */
            if (!DirPartyRelationship::find(DirRelationshipTypeTable::findBySystemType(DirSystemRelationshipType::ContactPerson).RelationshipTypeId,
                                            this.Party, 
                                            contactPerson.Party                                                                                         ).RecId)
            {
                continue;
            }

            buf2buf(contactPerson, newContactPerson);
            newContactPerson.CustAccount        = '';
            /*  2009
            newContactPerson.VendAccount        = '';
            */
            newContactPerson.ContactPersonId    = '';
            newContactPerson.insert();
        }
    }
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_companyBusRelTable">smmBusRelTable</param>
public void copyFromSmmBusRelTable(smmBusRelTable       _companyBusRelTable)
{
    this.AVASendExcel       = _companyBusRelTable.AVASendExcel;
    this.Blocked            = _companyBusRelTable.Blocked;
    this.CompanyChain       = _companyBusRelTable.CompanyChain;
    this.CompanyIdSiret     = _companyBusRelTable.CompanyIdSiret;
    this.CompanyNAFCode     = _companyBusRelTable.CompanyNAFCode;
    this.CreditMax          = _companyBusRelTable.CreditMax;
    this.CreditRating       = _companyBusRelTable.CreditRating;
    this.Currency           = _companyBusRelTable.Currency;
    if (CustGroup::find(_companyBusRelTable.CustGroup))
    {
        this.CustGroup   = _companyBusRelTable.CustGroup;
    }
    if (DestinationCode::find(_companyBusRelTable.DestinationCodeId))
    {
        this.DestinationCodeId = _companyBusRelTable.DestinationCodeId;
    }
    this.DirectMail         = _companyBusRelTable.DirectMail;
    if (DlvMode::find(_companyBusRelTable.DlvMode))
    {
        this.DlvMode        = _companyBusRelTable.DlvMode;
    }
    if (DlvTerm::find(_companyBusRelTable.DlvTerm))
    {
        this.DlvTerm        = _companyBusRelTable.DlvTerm;
    }
    this.FiscalCode         = _companyBusRelTable.FiscalCode;
    this.FreightZone        = _companyBusRelTable.FreightZone;
    this.Imported           = _companyBusRelTable.Imported;
    this.InclTax            = _companyBusRelTable.InclTax;
    this.KCS_CRMCashDisc    = _companyBusRelTable.KCS_CRMCashDisc;
    this.KCS_CRMPaymMode    = _companyBusRelTable.KCS_CRMPaymMode;
    this.KCS_CRMPaymTermId  = _companyBusRelTable.KCS_CRMPaymTermId;
    this.KCS_KMSDoSync      = _companyBusRelTable.KCS_KMSDoSync;
    this.KCS_KMSSyncBlocked = _companyBusRelTable.KCS_KMSSyncBlocked;
    this.KCS_LimitGroupName = _companyBusRelTable.KCS_LimitGroupName;
    this.KCS_MaxBonusAmount = _companyBusRelTable.KCS_MaxBonusAmount;
    this.KCS_QuotationEnabled = _companyBusRelTable.KCS_QuotationEnabled;
    this.KCS_RequestEnabled   = _companyBusRelTable.KCS_RequestEnabled;
    this.KCS_SalesGroup       = _companyBusRelTable.KCS_SalesGroup;
    this.LineOfBusinessId     = _companyBusRelTable.LineOfBusinessId;
    this.MCRPackedExtensions  = _companyBusRelTable.MCRPackedExtensions;
    this.MainContactWorker    = _companyBusRelTable.MainContactWorker;
    this.MandatoryCreditLimit = _companyBusRelTable.MandatoryCreditLimit;
    this.Memo                 = _companyBusRelTable.Memo;
    this.OneTimeRelation      = _companyBusRelTable.OneTimeRelation;
    this.OpenFromTime         = _companyBusRelTable.OpenFromTime;
    this.OpenToTime           = _companyBusRelTable.OpenToTime;
    this.Party                = _companyBusRelTable.Party;
    this.SalesCalendarId      = _companyBusRelTable.SalesCalendarId;           
    this.SalesDistrict        = _companyBusRelTable.SalesDistrict;
    this.Status               = _companyBusRelTable.Status;
}

/// <summary>
///     AVA <c>displayAVACustomerNames</c> method.
/// </summary>
/// <returns>
///     <c>LogisticsAddressing</c> as return value
/// </returns>
display LogisticsAddressing displayAVAsmmBusRelNames()
{
    LogisticsAddressing     retVal;

    LogisticsPostalAddress  locLogisticsPostalAddress;

    locLogisticsPostalAddress               = this.postalAddress();
    if(locLogisticsPostalAddress.RecId)
    {
        retVal = locLogisticsPostalAddress.NDXLogisticsLocationName1;
        if(retVal && locLogisticsPostalAddress.NDXLogisticsLocationName2)
        {
            retVal += '\n';
        }
        retVal += locLogisticsPostalAddress.NDXLogisticsLocationName2;
        if(retVal && locLogisticsPostalAddress.NDXLogisticsLocationName3)
        {
            retVal += '\n';
        }
        retVal += locLogisticsPostalAddress.NDXLogisticsLocationName3;
    }
    return retVal;
}

