/// </summary>
/// <param name="_updateMasterTables">
///     <c>boolean</c> as type
/// </param>
public void update(boolean _updateMasterTables)
{
    next update(_updateMasterTables);

    this.avaUpdateSegment();
}

/// <summary>
///     AVA <c>update</c> method.
///     AVA - Schneider 03.05.2024
///     Inserts an element into a table and updates the CRM transaction log.
/// </summary>
public void insert()
{
    next insert();

    this.avaUpdateSegmentWhenInserted();
}

/// <summary>
///     AVA <c>updateSegment</c> method.
/// </summary>
public void avaUpdateSegment()
{
    smmBusRelTable      locsmmBusRelTable;
    smmBusRelTable      locsmmBusRelTableTmp;
    smmBusRelTypeGroup  locsmmBusRelTypeGroup;
    container           locDataAreaIdList;
    smmSegmentId        locsmmSegmentId;
    smmSubsegmentId     locsmmSubsegmentId;

    locDataAreaIdList   = connull();
    locDataAreaIdList   = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    locsmmSegmentId     = this.Segment;
    locsmmSubsegmentId  = this.Subsegment;

    while select crosscompany:locDataAreaIdList locsmmBusRelTable
    where locsmmBusRelTable.Party   == this.Party
    {
        //current dataAreaId is not taken into account
        if(locsmmBusRelTable.DataAreaId != this.DataAreaId)
        {
            changecompany(locsmmBusRelTable.DataAreaId)
            {
                locsmmBusRelTableTmp = null;
                locsmmBusRelTableTmp = smmBusRelTable::findByParty(this.Party, true);

                if(     locsmmBusRelTableTmp.RecId
                    && (    locsmmBusRelTableTmp.Segment    != locsmmSegmentId 
                        ||  locsmmBusRelTableTmp.Subsegment != locsmmSubsegmentId   )   )
                {
                    locsmmBusRelTableTmp.Segment    = locsmmSegmentId;
                    locsmmBusRelTableTmp.Subsegment = locsmmSubsegmentId;
                    if(locsmmBusRelTableTmp.validateWrite())
                    {
                        ttsbegin;
                        locsmmBusRelTableTmp.doUpdate();

                        locsmmBusRelTypeGroup = smmBusRelTypeGroup::find(locsmmBusRelTableTmp.BusRelTypeId);
                        switch (locsmmBusRelTypeGroup.TableType)
                        {
                            case smmBusRelTypeSourceTable::Customer :
                                // Write relation information back to the customer
                                locsmmBusRelTableTmp.updateCustTable();
                                break;

                            case smmBusRelTypeSourceTable::Vendor :
                                // Write relation information back to the vendor
                                locsmmBusRelTableTmp.updateVendTable();
                                break;
                        }
                        ttscommit;
                    }
                }
            }
        }
    }
}

/// <summary>
///     AVA <c>avaUpdateSegmentOnCreate</c> method.
///     AVA - Schneider 10.06.2024
/// </summary>
 public void avaUpdateSegmentWhenInserted()
 {
     smmSegmentId        locsmmSegmentId;
     smmSubsegmentId     locsmmSubsegmentId;
     container           locDataAreaIdList;
     smmBusRelTable      locsmmBusRelTable;
     smmBusRelTable      locsmmBusRelTableTmp;

     locsmmSegmentId     = this.Segment;
     locsmmSubsegmentId  = this.Subsegment;

     if(     locsmmSegmentId    == ''
         &&  locsmmSubsegmentId == '')
     {
         locDataAreaIdList   = connull();
         locDataAreaIdList   = AVAKBVBuildingProjectHelper::getAllBPCompanies();

         select firstonly crosscompany:locDataAreaIdList locsmmBusRelTable
         where   locsmmBusRelTable.Party             == this.Party
             &&  locsmmBusRelTable.DataAreaId        != this.DataAreaId
             &&  (   locsmmBusRelTable.Segment       != ''
                 ||  locsmmBusRelTable.Subsegment    != ''   );

         if(locsmmBusRelTable.RecId)
         {
             this.selectForUpdate(true);
             this.Segment    = locsmmBusRelTable.Segment;
             this.Subsegment = locsmmBusRelTable.Subsegment;
             this.update();
         }
     }
     else
     {
         this.avaUpdateSegment();
     }
 }
